draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/4, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(100 + i*100 + 50*Math.cos(t + i), 100 + 20*Math.sin(t + i*2), 20 + 10*Math.sin(t + i), 0, 2*Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // tree
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2, H - 150 - 50*Math.sin(t));
  ctx.stroke();

  // bird
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(W/2 + 100*Math.cos(t), H - 200 - 50*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100*Math.cos(t), H - 200 - 50*Math.sin(t));
  ctx.lineTo(W/2 + 100*Math.cos(t) + 20*Math.cos(t + Math.PI/2), H - 200 - 50*Math.sin(t) + 20*Math.sin(t + Math.PI/2));
  ctx.stroke();

  ctx.restore();
}
